package com.example.starter.incident;

/**
 * 事件状态机：REPORTED → COMMANDING → CONTAINED → RESOLVED → CLOSED。
 * 只允许沿箭头前进一步，不允许跳转或回退；REPORTED → COMMANDING 仅能通过接管完成。
 */
public enum IncidentStatus {

    /** 已上报，尚无指挥人。 */
    REPORTED,

    /** 已接管，指挥人处置中。 */
    COMMANDING,

    /** 已控制。 */
    CONTAINED,

    /** 已解决，可由当前指挥人关闭。 */
    RESOLVED,

    /** 已关闭，终态，禁止任何写入。 */
    CLOSED;

    /**
     * 返回当前状态经状态变更接口可到达的下一状态；不可变更时返回 null。
     */
    public IncidentStatus next() {
        return switch (this) {
            case COMMANDING -> CONTAINED;
            case CONTAINED -> RESOLVED;
            case RESOLVED -> CLOSED;
            default -> null;
        };
    }
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 命令幂等键实体，对应 command_keys 表。
 * requestHash 为请求规范化参数的摘要；responseBody 为首次成功响应的 JSON，
 * 用于同键同参重放；responseStatus/responseBody 在事务提交前必定写入。
 */
public record CommandKeyRecord(
        long id,
        String commandKey,
        String operation,
        String requestHash,
        Integer responseStatus,
        String responseBody,
        Instant createdAt) {
}

