        if (model.isEmpty()) return;
        Fraction residual = currentResidual(incidentId, model.get());
        if (!ResidualRisk.withinLimit(residual, model.get().residualLimit())) {
            throw ApiException.unprocessable("RESIDUAL_RISK_EXCEEDED",
